import jwt
import datetime
from functools import wraps
from flask import request, g, current_app
from app.models.user import User


def create_access_token(user_id: int) -> str:
    payload = {
        "sub": user_id,
        "iat": datetime.datetime.utcnow(),
        "exp": datetime.datetime.utcnow() + datetime.timedelta(
            seconds=current_app.config["JWT_ACCESS_TOKEN_EXPIRES"]
        ),
    }
    return jwt.encode(payload, current_app.config["JWT_SECRET"], algorithm=current_app.config["JWT_ALGORITHM"])


def decode_token(token: str) -> dict | None:
    try:
        return jwt.decode(
            token,
            current_app.config["JWT_SECRET"],
            algorithms=[current_app.config["JWT_ALGORITHM"]],
        )
    except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return None


def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return {"error": "Missing or invalid Authorization header"}, 401
        token = auth_header.split(" ", 1)[1]
        payload = decode_token(token)
        if payload is None:
            return {"error": "Invalid or expired token"}, 401
        user = User.query.get(payload["sub"])
        if user is None or not user.is_active:
            return {"error": "User not found or deactivated"}, 401
        g.current_user = user
        return f(*args, **kwargs)

    return decorated


def admin_required(f):
    @wraps(f)
    @login_required
    def decorated(*args, **kwargs):
        if g.current_user.role != "admin":
            return {"error": "Admin privileges required"}, 403
        return f(*args, **kwargs)

    return decorated


def optional_login(f):
    """If a valid token is present, load the user; otherwise continue anonymously."""

    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if auth_header.startswith("Bearer "):
            token = auth_header.split(" ", 1)[1]
            payload = decode_token(token)
            if payload is not None:
                user = User.query.get(payload["sub"])
                if user and user.is_active:
                    g.current_user = user
                    return f(*args, **kwargs)
        g.current_user = None
        return f(*args, **kwargs)

    return decorated

from marshmallow import Schema, ValidationError
from flask import request


def validate_json(schema: Schema):
    """Decorator that validates request JSON against a Marshmallow schema."""

    def decorator(f):
        def wrapper(*args, **kwargs):
            json_data = request.get_json(silent=True)
            if json_data is None:
                return {"error": "Request body must be valid JSON"}, 400
            try:
                validated = schema.load(json_data)
            except ValidationError as err:
                return {"error": "Validation failed", "details": err.messages}, 422
            request.validated_data = validated
            return f(*args, **kwargs)

        wrapper.__name__ = f.__name__
        return wrapper

    return decorator


def validate_query(schema: Schema):
    """Decorator that validates query parameters against a Marshmallow schema."""

    def decorator(f):
        def wrapper(*args, **kwargs):
            try:
                validated = schema.load(request.args)
            except ValidationError as err:
                return {"error": "Invalid query parameters", "details": err.messages}, 422
            request.validated_query = validated
            return f(*args, **kwargs)

        wrapper.__name__ = f.__name__
        return wrapper

    return decorator

from flask import Blueprint, jsonify
from werkzeug.exceptions import HTTPException


errors_bp = Blueprint("errors", __name__)


@errors_bp.app_errorhandler(400)
def bad_request(e):
    return jsonify(error="Bad request", message=str(e.description if hasattr(e, "description") else e)), 400


@errors_bp.app_errorhandler(401)
def unauthorized(e):
    return jsonify(error="Unauthorized", message=str(e.description if hasattr(e, "description") else e)), 401


@errors_bp.app_errorhandler(403)
def forbidden(e):
    return jsonify(error="Forbidden", message=str(e.description if hasattr(e, "description") else e)), 403


@errors_bp.app_errorhandler(404)
def not_found(e):
    return jsonify(error="Not found", message=str(e.description if hasattr(e, "description") else e)), 404


@errors_bp.app_errorhandler(422)
def unprocessable(e):
    return jsonify(error="Unprocessable entity", message=str(e.description if hasattr(e, "description") else e)), 422


@errors_bp.app_errorhandler(429)
def too_many_requests(e):
    return jsonify(error="Rate limit exceeded", message=str(e.description)), 429


@errors_bp.app_errorhandler(500)
def internal_error(e):
    return jsonify(error="Internal server error", message="An unexpected error occurred"), 500


@errors_bp.app_errorhandler(Exception)
def handle_generic(e):
    if isinstance(e, HTTPException):
        return jsonify(error=e.name, message=e.description), e.code
    return jsonify(error="Internal server error", message=str(e)), 500

import datetime
import jwt
from app.extensions import db
from app.models.user import User
from app.middleware.auth import create_access_token


def register_user(username: str, email: str, password: str) -> tuple[dict, int]:
    if User.query.filter_by(username=username).first():
        return {"error": "Username already taken"}, 409
    if User.query.filter_by(email=email).first():
        return {"error": "Email already registered"}, 409

    user = User(username=username, email=email)
    user.set_password(password)
    db.session.add(user)
    db.session.commit()
    return {
        "message": "User registered successfully",
        "user": user.to_dict(),
    }, 201


def login_user(username: str, password: str) -> tuple[dict, int]:
    user = User.query.filter_by(username=username).first()
    if user is None or not user.check_password(password):
        return {"error": "Invalid username or password"}, 401
    if not user.is_active:
        return {"error": "Account is deactivated"}, 403

    token = create_access_token(user.id)
    return {"access_token": token, "token_type": "Bearer", "user": user.to_dict()}, 200

import math
from flask import request as flask_request


def paginate(query, page: int = 1, per_page: int = 20, schema_func=None):
    total = query.count()
    total_pages = max(1, math.ceil(total / per_page))
    page = max(1, min(page, total_pages))
    items = query.offset((page - 1) * per_page).limit(per_page).all()
    data = [schema_func(item) if schema_func else item.to_dict() for item in items]

    prev_url = None
    next_url = None
    try:
        if page > 1:
            prev_url = f"{flask_request.base_url}?page={page - 1}&per_page={per_page}"
        if page < total_pages:
            next_url = f"{flask_request.base_url}?page={page + 1}&per_page={per_page}"
    except RuntimeError:
        pass

    return {
        "data": data,
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "has_prev": page > 1,
            "has_next": page < total_pages,
            "prev_url": prev_url,
            "next_url": next_url,
        },
    }

from flask import Blueprint, request, g
from app.api.v1.schemas import RegisterSchema, LoginSchema
from app.middleware.auth import login_required
from app.middleware.validation import validate_json
from app.services.auth_service import register_user, login_user
from app.services.audit import log_audit

auth_bp = Blueprint("auth_v1", __name__, url_prefix="/api/v1/auth")


@auth_bp.route("/register", methods=["POST"])
@validate_json(RegisterSchema())
def register():
    data = request.validated_data
    resp, status = register_user(data["username"], data["email"], data["password"])
    if status == 201:
        log_audit("register", "user", None, f"User {data['username']} registered")
    return resp, status


@auth_bp.route("/login", methods=["POST"])
@validate_json(LoginSchema())
def login():
    data = request.validated_data
    resp, status = login_user(data["username"], data["password"])
    if status == 200:
        log_audit("login", "user", None, f"User {data['username']} logged in")
    return resp, status


@auth_bp.route("/me", methods=["GET"])
@login_required
def me():
    log_audit("profile_read", "user", g.current_user.id)
    return g.current_user.to_dict(), 200

from flask import Blueprint, request, g
from app.extensions import db, limiter
from app.models.item import Item
from app.api.v1.schemas import ItemSchema, ItemUpdateSchema, PaginationSchema
from app.middleware.auth import login_required
from app.middleware.validation import validate_json, validate_query
from app.services.audit import log_audit
from app.utils.pagination import paginate

items_bp = Blueprint("items_v1", __name__, url_prefix="/api/v1/items")


@items_bp.route("", methods=["GET"])
@login_required
@validate_query(PaginationSchema())
def list_items():
    args = request.validated_query
    query = Item.query.filter_by(owner_id=g.current_user.id).order_by(Item.created_at.desc())
    result = paginate(query, page=args["page"], per_page=args["per_page"])
    return result, 200


@items_bp.route("", methods=["POST"])
@login_required
@limiter.limit("30 per minute")
@validate_json(ItemSchema())
def create_item():
    data = request.validated_data
    item = Item(name=data["name"], description=data.get("description"), owner_id=g.current_user.id)
    db.session.add(item)
    db.session.commit()
    log_audit("create", "item", item.id, f"Item '{item.name}' created")
    return item.to_dict(), 201


@items_bp.route("/<int:item_id>", methods=["GET"])
@login_required
def get_item(item_id):
    item = Item.query.filter_by(id=item_id, owner_id=g.current_user.id).first()
    if item is None:
        return {"error": "Item not found"}, 404
    log_audit("read", "item", item.id)
    return item.to_dict(), 200


@items_bp.route("/<int:item_id>", methods=["PUT"])
@login_required
@validate_json(ItemUpdateSchema())
def update_item(item_id):
    item = Item.query.filter_by(id=item_id, owner_id=g.current_user.id).first()
    if item is None:
        return {"error": "Item not found"}, 404

    data = request.validated_data
    if "name" in data:
        item.name = data["name"]
    if "description" in data:
        item.description = data["description"]
    db.session.commit()
    log_audit("update", "item", item.id, f"Item '{item.name}' updated")
    return item.to_dict(), 200


@items_bp.route("/<int:item_id>", methods=["DELETE"])
@login_required
def delete_item(item_id):
    item = Item.query.filter_by(id=item_id, owner_id=g.current_user.id).first()
    if item is None:
        return {"error": "Item not found"}, 404

    db.session.delete(item)
    db.session.commit()
    log_audit("delete", "item", item_id)
    return {"message": "Item deleted"}, 200

from flask import Blueprint, request, g
from app.extensions import db
from app.models.user import User
from app.api.v1.schemas import PaginationSchema, UserUpdateSchema
from app.middleware.auth import login_required, admin_required
from app.middleware.validation import validate_json, validate_query
from app.services.audit import log_audit
from app.utils.pagination import paginate

users_bp = Blueprint("users_v1", __name__, url_prefix="/api/v1/users")


@users_bp.route("", methods=["GET"])
@admin_required
@validate_query(PaginationSchema())
def list_users():
    args = request.validated_query
    query = User.query.order_by(User.created_at.desc())
    result = paginate(query, page=args["page"], per_page=args["per_page"])
    log_audit("list", "user")
    return result, 200


@users_bp.route("/<int:user_id>", methods=["GET"])
@login_required
def get_user(user_id):
    if g.current_user.role != "admin" and g.current_user.id != user_id:
        return {"error": "Access denied"}, 403

    user = User.query.get(user_id)
    if user is None:
        return {"error": "User not found"}, 404

    log_audit("read", "user", user_id)
    return user.to_dict(), 200


@users_bp.route("/<int:user_id>", methods=["PUT"])
@admin_required
@validate_json(UserUpdateSchema())
def update_user(user_id):
    user = User.query.get(user_id)
    if user is None:
        return {"error": "User not found"}, 404

    data = request.validated_data
    for field in ["email", "role", "is_active"]:
        if field in data:
            setattr(user, field, data[field])

    db.session.commit()
    log_audit("update", "user", user_id)
    return user.to_dict(), 200


@users_bp.route("/<int:user_id>", methods=["DELETE"])
@admin_required
def delete_user(user_id):
    user = User.query.get(user_id)
    if user is None:
        return {"error": "User not found"}, 404

    db.session.delete(user)
    db.session.commit()
    log_audit("delete", "user", user_id)
    return {"message": "User deleted"}, 200

